mapper.select:
select * from inspect_task


        update_time >= #{period.begin}


        and update_time <= #{period.end}


        and tenant = #{tenant} and parent_id = 0

SELECT it.receive_ids as name, COALESCE(ROUND( SUM( TIMESTAMPDIFF( MINUTE, it.begin_time, it.end_time )) / COUNT( it.id ), 0 ),0) avgTime FROM `inspect_task` it WHERE it.`status` = 'OVER'
and it.create_time >= #{period.begin}
and it.create_time <= #{period.end}
GROUP BY it.receive_ids ORDER BY avgTime
DESC
LIMIT 5

SELECT COALESCE (COUNT( it.id ),0) taskHandlerNumber, COALESCE (SUM(TIMESTAMPDIFF( MINUTE, it.begin_time, it.end_time )),0) taskTotalTime FROM `inspect_task` it WHERE it.`status` = 'OVER'
and it.create_time >= #{period.begin}
and it.create_time <= #{period.end}

SELECT COUNT(1)
FROM inspect_task



        AND id IN

            #{taskId}




        AND create_time >= #{param.period.begin}




            AND status IN

                #{status}



            AND status = #{param.status}




        AND create_time <= #{param.period.end}



        AND plan_id IN

            #{planId}



        AND (

        valid_begin_time IS NOT NULL
        AND limit_total_minute IS NOT NULL
        AND (

        (end_time IS NOT NULL AND end_time > DATE_ADD(valid_begin_time, INTERVAL limit_total_minute MINUTE))
        OR

        (end_time IS NULL AND NOW() > DATE_ADD(valid_begin_time, INTERVAL limit_total_minute MINUTE))
        )
        )
